var REGULATIONS = [{"code":"1.71","topic":"delta","about":"What the Delta legally is","title":"Sacramento-San Joaquin River Delta","text":"Sacramento-San Joaquin River Delta The Sacramento-San Joaquin River Delta includes all rivers, sloughs, canals, cuts, forebays, and flooded islands within the area south of Interstate 80 to its junction with Highway 50, and south of Highway 50 via the Pioneer Bridge to its junction with Highway 99, west of Highway 99, north of Interstate 580, 205, and Highway 120, and east of Interstate 680.","parts":[],"source":"CCR Title 14"},{"code":"2.10(c)(1)","topic":"delta","about":"Hook gaps in the Delta","title":"Hook And Weight Restrictions","text":"No person shall use any single hook with a gap greater than 1 inch or any multiple hook with a gap greater than 3/4 inch.","parts":[],"source":"CCR Title 14"},{"code":"2.25(b)(1)","topic":"delta","about":"Bow and arrow fishing in the Delta","title":"Bow and Arrow Fishing","text":"Within the boundaries of the Sacramento-San Joaquin River Delta (See Section1.71)","parts":[],"source":"CCR Title 14"},{"code":"5.00(a)(1)","topic":"bass","about":"Black bass: lakes, reservoirs and the Delta","title":"Black Bass","text":"Lakes/Reservoirs and the Sacramento-San Joaquin Delta: The following waters, except for those listed in subsection (b), are open to fishing all year, with a 12-inch total length minimum size limit and a five-fish daily bag limit: All lakes and reservoirs in the State, and the Sacramento-San Joaquin River Delta, (see Section 1.71 for definition of the Delta).","parts":[],"source":"CCR Title 14"},{"code":"5.75(a)","topic":"striper","about":"Striped bass: open season","title":"Striped Bass","text":"Open season: All year except for closures listed in special regulations.","parts":[],"source":"CCR Title 14"},{"code":"5.75(b)","topic":"striper","about":"Striped bass: limit","title":"Striped Bass","text":"Limit: Two, except in waters listed in (d) below.","parts":[],"source":"CCR Title 14"},{"code":"5.75(c)","topic":"striper","about":"Striped bass: minimum size","title":"Striped Bass","text":"Minimum size: 18 inches total length except in waters listed in (d) below.","parts":[],"source":"CCR Title 14"},{"code":"5.75(e)","topic":"striper","about":"Striped bass: hybrids","title":"Striped Bass","text":"For the purpose of these regulations, any striped bass hybrid with white bass is considered to be striped bass.","parts":[],"source":"CCR Title 14"},{"code":"5.80(a)","topic":"sturgeon","about":"White sturgeon: open season","title":"Inland White Sturgeon","text":"Open season:","parts":[{"code":"5.80(a)(1)","text":"From October 1 through June 30: from the west Carquinez Bridge east to downstream of the confluence of the Feather River on the Sacramento River and downstream of the I-5 bridge on the San Joaquin River"},{"code":"5.80(a)(2)","text":"From October 1 through December 31: upstream of the confluence of the Feather River to the Highway 162 Bridge on the Sacramento River and upstream of the I-5 bridge on the San Joaquin River."},{"code":"5.80(a)(3)","text":"Year-round: all tributaries of the Sacramento and San Joaquin Rivers are closed."}],"source":"CCR Title 14"},{"code":"5.80(b)","topic":"sturgeon","about":"White sturgeon: daily limit","title":"Inland White Sturgeon","text":"Daily limit: Zero fish.","parts":[],"source":"CCR Title 14"},{"code":"5.80(c)","topic":"sturgeon","about":"White sturgeon: annual limit","title":"Inland White Sturgeon","text":"Annual bag limit: zero fish per calendar year statewide.","parts":[],"source":"CCR Title 14"},{"code":"5.80(d)","topic":"sturgeon","about":"White sturgeon: methods of take","title":"Inland White Sturgeon","text":"Methods of take: Only one single point, single shank, barbless hook shall be used on a line when taking sturgeon. The sturgeon must voluntarily take the bait or lure inside its mouth. No sturgeon may be taken by trolling, snagging or by the use of firearms. Sturgeon may not be gaffed, nor shall any person use any type of firearm or snare to take any sturgeon. For the purposes of this section, a snare is a flexible loop made from any material that can be tightened like a noose around any part of the fish.","parts":[],"source":"CCR Title 14"},{"code":"5.80(e)","topic":"sturgeon","about":"White sturgeon: handling and removal from water","title":"Inland White Sturgeon","text":"Handling and removal from water. Any sturgeon greater than 60 inches fork length may not be removed from the water and shall be released immediately. Sturgeon of any size shall not be held out of water suspended by the gills, gill plates, mouth, or solely by the tail, and shall not be dragged across the ground, boat decks, or piers. Lip gripper devices shall not be used on sturgeon.","parts":[],"source":"CCR Title 14"},{"code":"5.80(f)","topic":"sturgeon","about":"White sturgeon: report card required","title":"Inland White Sturgeon","text":"Sturgeon Fishing Report Card Required: All anglers must have a valid Sturgeon Fishing Report Card in their possession while fishing for white sturgeon. Anglers must complete and return the report card pursuant to regulations in this Section and Section 1.74.","parts":[],"source":"CCR Title 14"},{"code":"5.80(i)","topic":"sturgeon","about":"Sturgeon closure, Sierra and Valley District","title":"Inland White Sturgeon","text":"Special Sierra and Valley District Sturgeon Closure from January 1 to December 31 (Shasta, Tehama, Butte and Glenn cos)","parts":[{"code":"5.80(i)(1)","text":"Sacramento River from Keswick Dam to the Highway 162 Bridge."}],"source":"CCR Title 14"},{"code":"5.80(j)","topic":"sturgeon","about":"Sturgeon closure, Yolo Bypass","title":"Inland White Sturgeon","text":"Special Yolo Bypass Flood Control System Sturgeon Closure. It is unlawful to take any sturgeon in the Yolo Bypass, Toe Drain Canal, and Tule Canal upstream of Lisbon Weir at any time.","parts":[],"source":"CCR Title 14"},{"code":"5.81(a)","topic":"sturgeon","about":"Green sturgeon may not be taken","title":"Green Sturgeon","text":"Green sturgeon may not be taken or possessed","parts":[],"source":"CCR Title 14"},{"code":"5.81(b)","topic":"sturgeon","about":"Green sturgeon: removal from water","title":"Green Sturgeon","text":"Green sturgeon may not be removed from the water and shall be released immediately.","parts":[],"source":"CCR Title 14"},{"code":"5.81(c)","topic":"sturgeon","about":"Green sturgeon: reporting","title":"Green Sturgeon","text":"Green sturgeon taken and released incidentally to white sturgeon fishing shall be reported on a Sturgeon Fishing Report Card issued by the department, in accordance with procedures defined in Sections 1.74 and 5.80, Title 14, CCR.","parts":[],"source":"CCR Title 14"},{"code":"1.73(a)","topic":"salmon","about":"What counts as salmon","title":"Salmon","text":"Salmon includes Chinook, coho, pink, chum, and sockeye salmon.","parts":[],"source":"CCR Title 14"},{"code":"1.75","topic":"salmon","about":"Salmon spawning areas","title":"Salmon Spawning Areas","text":"Salmon Spawning Areas No salmon may be taken or possessed on any salmon spawning area when it is closed to salmon fishing.","parts":[],"source":"CCR Title 14"}];
